    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SCP_XLS_PSI_GLOBAL_SMALL SAVE LOGIC';
    D_EVENT_DATE  := SYSDATE;
    IF P_IS_DEBUG = 0 THEN
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_USER_ID);
    END IF;

    BEGIN

        /* ------------------------------------------------------------------------------------- */
        /* 입력된 버전과 현재 버전이 다를 경우 처리 생략 */
        /* ------------------------------------------------------------------------------------- */
        /* ------------------------------------------------------------------------------------------
         *   if @P_PLAN_TYPE = 'FN'  RAISERROR ('PLAN TYPE "FN" CANNOT BE UPDATED', 10 , 1)
         *   원문 꼬리주석 : With a severity of 10 or lower in a TRY block.
         * T-SQL RAISERROR 의 severity 10 은 정보성 메시지라 TRY 블록을 중단시키지 않고 CATCH 로도 가지 않는다
         * ------------------------------------------------------------------------------------------ */
        IF P_PLAN_TYPE = 'FN' THEN
            DBMS_OUTPUT.PUT_LINE('PLAN TYPE "FN" CANNOT BE UPDATED');
        END IF;
        /* ------------------------------------------------------------------------------------- */
        /* 입력된 버전과 현재 버전이 다를 경우 EXCEPTION */
        /* ------------------------------------------------------------------------------------- */
        /* 원본 L71~75 SELECT TOP 1 ... (WHERE 절 없음). 0 행이면 MSSQL 은 변수를 건드리지 않아
         * 파라미터 초기값이 유지된다 -> SELECT INTO(NO_DATA_FOUND) 대신 커서 FOR 루프로 재현. */
        FOR R IN (SELECT DIVISION_ID
                       , PLAN_START_YYYYMMDD
                       , PLAN_TYPE
                       , SEQ
                    FROM SCP_XLS_PSI_GLOBAL_SMALL
                   WHERE ROWNUM = 1) LOOP
            V_DIVISION_ID         := R.DIVISION_ID;
            V_PLAN_START_YYYYMMDD := R.PLAN_START_YYYYMMDD;
            V_PLAN_TYPE           := R.PLAN_TYPE;
            V_SEQ                 := R.SEQ;
        END LOOP;

        IF (P_DIVISION_ID <> V_DIVISION_ID OR P_PLAN_START_YYYYMMDD <> V_PLAN_START_YYYYMMDD OR P_PLAN_TYPE <> V_PLAN_TYPE OR P_SEQ <> V_SEQ) THEN
            RAISE_APPLICATION_ERROR(-20001, 'PLAN DATA IS DIFFERENT FROM CURRENT PLAN  ');
        END IF;

        IF P_MEASURE NOT  IN  ('SHIP_PLAN', 'CELL_PROD') THEN
            RAISE_APPLICATION_ERROR(-20001, 'PLAN DATA CANNOT BE SAVED WITH REQUESTED MEASURE ');
        END IF;

        /* 데이터 프로세싱 시작 */
        /* 원본 L85 : DECLARE @CHANGED_DATA TABLE (YYYYMMDD  VARCHAR(8),  QTY  NUMERIC (20,10)) */
        DELETE
          FROM GT_XADSM_CHANGED_DATA;

        IF (P_PLAN_START_YYYYMMDD <> P_CREATE_FROM_YYYYMMDD) THEN
            /* XLS_KEY1 시작 */
            V_YEAR2_KEY := '';

            FOR R IN (SELECT Y.XLS_KEY1
                        FROM ( /* 1차년도 */
                              SELECT *
                                FROM SCP_XLS_PSI_GLOBAL_SMALL
                               WHERE DIVISION_ID          = P_DIVISION_ID
                                 AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
                                 AND PLAN_TYPE            = P_PLAN_TYPE
                                 AND SEQ                  = P_SEQ
                                 AND CREATE_FROM_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                 AND XLS_KEY1             = V_XLS_KEY1 ) X
                           , SCP_XLS_PSI_GLOBAL_SMALL Y
                       WHERE Y.DIVISION_ID          = X.DIVISION_ID
                         AND Y.PLAN_START_YYYYMMDD  = X.PLAN_START_YYYYMMDD
                         AND Y.PLAN_TYPE            = X.PLAN_TYPE
                         AND Y.SEQ                  = X.SEQ
                         AND Y.CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
                         AND Y.OPERATION_GROUP      = X.OPERATION_GROUP
                         AND Y.CELL_ITEM_ID         = X.CELL_ITEM_ID
                         AND Y.ITEM_ID              = X.ITEM_ID
                         AND Y.TO_SITE              = X.TO_SITE
                         AND Y.PROJECT_CODE         = X.PROJECT_CODE
                         AND Y.INCOTERMS            = X.INCOTERMS
                         AND Y.FROM_SITE            = X.FROM_SITE
                         AND Y.TRANSPORT_MODE       = X.TRANSPORT_MODE
                         AND Y.PROD_LINE            = X.PROD_LINE
                         AND Y.BOD_ID               = X.BOD_ID
                         AND Y.MEASURE              = X.MEASURE) LOOP
                V_YEAR2_KEY := TO_CHAR(R.XLS_KEY1);
            END LOOP;

            /* SELECT @v_xls_key1   "요청된 XLS_KEY1 ", @v_link_xls_key1 AS "1차년도 XLS_KEY1"--TEST */

            V_XLS_KEY1 := CASE WHEN V_YEAR2_KEY IS NULL THEN 0 ELSE TO_NUMBER(V_YEAR2_KEY) END;

