         WHERE DIVISION_ID          = P_DIVISION_ID
           AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
           AND XLS_KEY1             = V_XLS_KEY1;

        /* 원본 L133 : IF @P_IS_DEBUG = 1 SELECT @P_MEASURE AS "@P_MEASURE", @QTY001 "@QTY001", @QTY002 "@QTY002" */
        IF P_IS_DEBUG = 1 THEN
            DBMS_OUTPUT.PUT_LINE('@P_MEASURE=' || P_MEASURE || ' @QTY001=' || TO_CHAR(P_QTY001) || ' @QTY002=' || TO_CHAR(P_QTY002));
        END IF;

        /* 주간정보 저장 */
        UPDATE SCP_XLS_PSI_GLOBAL_SMALL
           SET WQTY01 = QTY001 + QTY002 + QTY003 + QTY004 + QTY005 + QTY006 + QTY007
             , WQTY02 = QTY008 + QTY009 + QTY010 + QTY011 + QTY012 + QTY013 + QTY014
