             , WQTY26 = QTY176 + QTY177 + QTY178 + QTY179 + QTY180 + QTY181 + QTY182
             , WQTY27 = QTY183 + QTY184 + QTY185 + QTY186 + QTY187 + QTY188 + QTY189
             , WQTY28 = QTY190 + QTY191 + QTY192 + QTY193 + QTY194 + QTY195 + QTY196
             , WQTY29 = QTY197 + QTY198 + QTY199 + QTY200 + QTY201 + QTY202 + QTY203
             , WQTY30 = QTY204 + QTY205 + QTY206 + QTY207 + QTY208 + QTY209 + QTY210
             , WQTY31 = QTY211 + QTY212 + QTY213 + QTY214 + QTY215 + QTY216 + QTY217
             , WQTY32 = QTY218 + QTY219 + QTY220 + QTY221 + QTY222 + QTY223 + QTY224
             , WQTY33 = QTY225 + QTY226 + QTY227 + QTY228 + QTY229 + QTY230 + QTY231
             , WQTY34 = QTY232 + QTY233 + QTY234 + QTY235 + QTY236 + QTY237 + QTY238
             , WQTY35 = QTY239 + QTY240 + QTY241 + QTY242 + QTY243 + QTY244 + QTY245
             , WQTY36 = QTY246 + QTY247 + QTY248 + QTY249 + QTY250 + QTY251 + QTY252
             , WQTY37 = QTY253 + QTY254 + QTY255 + QTY256 + QTY257 + QTY258 + QTY259
             , WQTY38 = QTY260 + QTY261 + QTY262 + QTY263 + QTY264 + QTY265 + QTY266
             , WQTY39 = QTY267 + QTY268 + QTY269 + QTY270 + QTY271 + QTY272 + QTY273
             , WQTY40 = QTY274 + QTY275 + QTY276 + QTY277 + QTY278 + QTY279 + QTY280
             , WQTY41 = QTY281 + QTY282 + QTY283 + QTY284 + QTY285 + QTY286 + QTY287
             , WQTY42 = QTY288 + QTY289 + QTY290 + QTY291 + QTY292 + QTY293 + QTY294
             , WQTY43 = QTY295 + QTY296 + QTY297 + QTY298 + QTY299 + QTY300 + QTY301
             , WQTY44 = QTY302 + QTY303 + QTY304 + QTY305 + QTY306 + QTY307 + QTY308
             , WQTY45 = QTY309 + QTY310 + QTY311 + QTY312 + QTY313 + QTY314 + QTY315
             , WQTY46 = QTY316 + QTY317 + QTY318 + QTY319 + QTY320 + QTY321 + QTY322
             , WQTY47 = QTY323 + QTY324 + QTY325 + QTY326 + QTY327 + QTY328 + QTY329
             , WQTY48 = QTY330 + QTY331 + QTY332 + QTY333 + QTY334 + QTY335 + QTY336
             , WQTY49 = QTY337 + QTY338 + QTY339 + QTY340 + QTY341 + QTY342 + QTY343
             , WQTY50 = QTY344 + QTY345 + QTY346 + QTY347 + QTY348 + QTY349 + QTY350
             , WQTY51 = QTY351 + QTY352 + QTY353 + QTY354 + QTY355 + QTY356 + QTY357
             , WQTY52 = QTY358 + QTY359 + QTY360 + QTY361 + QTY362 + QTY363 + QTY364
         WHERE DIVISION_ID          = P_DIVISION_ID
           AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
           AND XLS_KEY1             = V_XLS_KEY1;

        IF P_MEASURE IN  ('SHIP_PLAN') THEN
            /* SHIP PLAN 시작 */
            /* 원본 L147~152 : 대입형 SELECT. 대상은 PK(DIVISION_ID, CREATE_FROM_YYYYMMDD, XLS_KEY1) 라 최대 1행이나 */
            FOR R IN (SELECT (CASE WHEN ATTRIBUTE3 IS NULL THEN '19900101' ELSE SUBSTR(ATTRIBUTE3, 1, 8) END) AS BOD_FROM
                           , (CASE WHEN ATTRIBUTE3 IS NULL THEN '29991231' ELSE SUBSTR(ATTRIBUTE3, GREATEST(LENGTH(ATTRIBUTE3) - 8 + 1, 1)) END) AS BOD_TO
                        FROM SCP_XLS_PSI_GLOBAL_SMALL
                       WHERE DIVISION_ID          = P_DIVISION_ID
                         AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
                         AND XLS_KEY1             = V_XLS_KEY1) LOOP
                V_BOD_FROM := R.BOD_FROM;
                V_BOD_TO   := R.BOD_TO;
            END LOOP;

            /* 변경데이터셋 */
            INSERT
              INTO GT_XADSM_CHANGED_DATA
                 ( YYYYMMDD
                 , QTY )
            SELECT A.TOKEN
                 , CAST(B.TOKEN AS NUMBER(20,10))
              FROM TABLE(UF_FX_STRING_SPLIT(P_YMD_STRINGS, ',')) A
                 , TABLE(UF_FX_STRING_SPLIT(P_QTY_STRINGS, ',')) B
             WHERE A.NR = B.NR
               AND B.TOKEN <> '-9';

            /* 원본 L163 : IF @P_IS_DEBUG = 1  SELECT '@CHANGED_DATA' as "@CHANGED_DATA",  * FROM @CHANGED_DATA */
            IF P_IS_DEBUG = 1 THEN
                FOR R IN (SELECT COUNT(*) CNT
                            FROM GT_XADSM_CHANGED_DATA) LOOP
                    DBMS_OUTPUT.PUT_LINE('@CHANGED_DATA ROWS=' || TO_CHAR(R.CNT));
                END LOOP;
            END IF;


            DELETE
              FROM GT_XADSM_SASPFG;

            INSERT
              INTO GT_XADSM_SASPFG
                 ( DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , BIZ_TYPE
                 , PROJECT_CODE
                 , ITEM_ID
                 , TO_SITE
                 , INCOTERMS
                 , FROM_SITE
                 , BOD_ID
                 , TRANSPORT_MODE
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , ATTRIBUTE1 )
            SELECT X.DIVISION_ID
                 , X.PLAN_START_YYYYMMDD
                 , X.PLAN_TYPE
                 , X.SEQ
                 , X.OPERATION_GROUP AS BIZ_TYPE
                 , X.PROJECT_CODE
                 , X.ITEM_ID
                 , X.TO_SITE
                 , X.INCOTERMS
                 , X.FROM_SITE
                 , X.BOD_ID
                 , X.TRANSPORT_MODE
                 , 'SHIP_PLAN_AMEND' AS MEASURE
                 , Y.YYYYMMDD
                 , Y.QTY
                 , P_DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
                 , P_DIVISION_ID AS ORIGIN_TO_DIVISION_ID
                 , '' AS ELECTRODE_TYPE
                 , X.ATTRIBUTE1
              FROM (SELECT *
                      FROM SCP_XLS_PSI_GLOBAL_SMALL
                     WHERE DIVISION_ID          = P_DIVISION_ID
                       AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
                       AND XLS_KEY1             = V_XLS_KEY1) X

              FULL OUTER JOIN GT_XADSM_CHANGED_DATA Y
                ON 1 = 1
             WHERE Y.YYYYMMDD BETWEEN V_BOD_FROM AND V_BOD_TO;


            IF P_IS_DEBUG = 1 THEN
                FOR R IN (SELECT COUNT(*) CNT
                            FROM GT_XADSM_SASPFG) LOOP
                    DBMS_OUTPUT.PUT_LINE('#SCP_ANL_SHIPMENT_PLAN_FG ROWS=' || TO_CHAR(R.CNT));
                END LOOP;
            END IF;

            MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG X
            USING GT_XADSM_SASPFG Y
               ON (0 = 0
              AND X.DIVISION_ID               = Y.DIVISION_ID           /* @P_DIVISION_ID			--  2021.10.25 튜닝개선요청에 따른 변경 */
              AND X.PLAN_START_YYYYMMDD       = Y.PLAN_START_YYYYMMDD   /* @@P_PLAN_START_YYYYMMDD */
              AND X.PLAN_TYPE                 = Y.PLAN_TYPE             /* @P_PLAN_TYPE */
              AND X.SEQ                       = Y.SEQ                   /* @P_SEQ */
              AND X.BIZ_TYPE                  = Y.BIZ_TYPE
              AND X.PROJECT_CODE              = Y.PROJECT_CODE
              AND X.ITEM_ID                   = Y.ITEM_ID
              AND X.TO_SITE                   = Y.TO_SITE
              AND X.INCOTERMS                 = Y.INCOTERMS
              AND X.FROM_SITE                 = Y.FROM_SITE
              AND X.BOD_ID                    = Y.BOD_ID
              AND X.MEASURE                   = Y.MEASURE
              AND X.YYYYMMDD                  = Y.YYYYMMDD)
            WHEN MATCHED THEN
            UPDATE
               SET X.QTY               = Y.QTY
                 , X.LAST_UPDATED_BY   = V_USER_ID_SIM
                 , X.LAST_UPDATE_DATE  = SYSDATE
            WHEN NOT MATCHED THEN
            INSERT ( DIVISION_ID
                   , PLAN_START_YYYYMMDD
                   , PLAN_TYPE
                   , SEQ
                   , BIZ_TYPE
                   , PROJECT_CODE
                   , ITEM_ID
                   , TO_SITE
                   , INCOTERMS
                   , FROM_SITE
                   , BOD_ID
                   , MEASURE
                   , YYYYMMDD
                   , QTY
                   , ORIGIN_FROM_DIVISION_ID
                   , ORIGIN_TO_DIVISION_ID
                   , ELECTRODE_TYPE
                   , CREATED_BY
                   , CREATION_DATE
                   , LAST_UPDATED_BY
                   , LAST_UPDATE_DATE )
            VALUES ( Y.DIVISION_ID
                   , Y.PLAN_START_YYYYMMDD
                   , Y.PLAN_TYPE
                   , Y.SEQ
                   , Y.BIZ_TYPE
                   , Y.PROJECT_CODE
                   , Y.ITEM_ID
                   , Y.TO_SITE
                   , Y.INCOTERMS
                   , Y.FROM_SITE
                   , Y.BOD_ID
                   , Y.MEASURE
                   , Y.YYYYMMDD
                   , Y.QTY
                   , Y.ORIGIN_FROM_DIVISION_ID
                   , Y.ORIGIN_TO_DIVISION_ID
                   , Y.ELECTRODE_TYPE
                   , V_USER_ID_SIM
                   , SYSDATE
                   , V_USER_ID_SIM
                   , SYSDATE );

            IF P_IS_DEBUG = 0 THEN
            INSERT
              INTO SCP_ANL_SHIPMENT_PLAN_FG_H
                 ( HISTORY_SEQ
                 , DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , BIZ_TYPE
                 , PROJECT_CODE
                 , ITEM_ID
                 , TO_SITE
                 , INCOTERMS
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_TO_DIVISION_ID
                 , ORIGIN_FROM_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , HISTORY_CREATION_DATE )
            SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H.NEXTVAL
                 , DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , BIZ_TYPE
                 , PROJECT_CODE
                 , ITEM_ID
                 , TO_SITE
                 , INCOTERMS
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_TO_DIVISION_ID
                 , ORIGIN_FROM_DIVISION_ID
                 , ELECTRODE_TYPE
                 , V_USER_ID_SIM
                 , SYSDATE
                 , V_USER_ID_SIM
                 , SYSDATE
                 , SYSDATE
              FROM GT_XADSM_SASPFG;
            END IF;

            /* SCP_ANL_SHIPMENT_PLAN_FIX (수정) */

            IF P_IS_DEBUG = 0 THEN
            UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
               SET X.QTY               = (SELECT Y.QTY
                                            FROM GT_XADSM_SASPFG Y
                                           WHERE 0 = 0
                                             AND X.DIVISION_ID  = Y.DIVISION_ID
                                             AND X.BIZ_TYPE     = Y.BIZ_TYPE
                                             AND X.PROJECT_CODE = Y.PROJECT_CODE
                                             AND X.ITEM_ID      = Y.ITEM_ID
                                             AND X.TO_SITE      = Y.TO_SITE
                                             AND X.FROM_SITE    = Y.FROM_SITE
                                             AND X.BOD_ID       = Y.BOD_ID
                                             AND X.YYYYMMDD     = Y.YYYYMMDD
                                             AND ROWNUM = 1)
                 , X.FIX_REASON        = 'SIMULATION UPDATE'
                 , X.ATTRIBUTE1        = 'Y'   /* History 구분을 위해 */
                 , X.LAST_UPDATED_BY   = V_USER_ID_SIM
                 , X.LAST_UPDATE_DATE  = SYSDATE
             WHERE EXISTS (SELECT 1
                             FROM GT_XADSM_SASPFG Y
                            WHERE 0 = 0
                              AND X.DIVISION_ID  = Y.DIVISION_ID
                              AND X.BIZ_TYPE     = Y.BIZ_TYPE
                              AND X.PROJECT_CODE = Y.PROJECT_CODE
                              AND X.ITEM_ID      = Y.ITEM_ID
                              AND X.TO_SITE      = Y.TO_SITE
                              AND X.FROM_SITE    = Y.FROM_SITE
                              AND X.BOD_ID       = Y.BOD_ID
                              AND X.YYYYMMDD     = Y.YYYYMMDD);
            END IF;

            /* ------------------------------------------------------------------------------------- */
            /* SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력 */
            /* ------------------------------------------------------------------------------------- */
            IF P_IS_DEBUG = 0 THEN
            INSERT
              INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
                 ( HISTORY_SEQ
                 , FIX_ID
                 , DIVISION_ID
                 , BIZ_TYPE
                 , ITEM_ID
                 , TO_SITE
                 , FROM_SITE
                 , PROJECT_CODE
                 , INCOTERMS
                 , BOD_ID
                 , YYYYMMDD
                 , QTY
                 , FIX_REASON
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , HISTORY_CREATION_DATE )
            SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL   /* 여러개 발생가능성 */
                 , FIX_ID
                 , DIVISION_ID
                 , BIZ_TYPE
                 , ITEM_ID
                 , TO_SITE
                 , FROM_SITE
                 , PROJECT_CODE
                 , INCOTERMS
                 , BOD_ID
                 , YYYYMMDD
                 , QTY
                 , FIX_REASON
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , V_USER_ID_SIM
                 , SYSDATE AS CREATION_DATE
                 , V_USER_ID_SIM AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , SYSDATE AS HISTORY_CREATION_DATE
              FROM SCP_ANL_SHIPMENT_PLAN_FIX
             WHERE ATTRIBUTE1 = 'Y';
            END IF;

            /* FIX  수정 */
            IF P_IS_DEBUG = 0 THEN
            UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
               SET X.ATTRIBUTE1 = NULL   /* History 구분을 위해 원상복구 */
             WHERE EXISTS (SELECT 1
                             FROM GT_XADSM_SASPFG Y
                            WHERE 0 = 0
                              AND X.DIVISION_ID  = Y.DIVISION_ID
                              AND X.BIZ_TYPE     = Y.BIZ_TYPE
                              AND X.PROJECT_CODE = Y.PROJECT_CODE
                              AND X.ITEM_ID      = Y.ITEM_ID
                              AND X.TO_SITE      = Y.TO_SITE
                              AND X.FROM_SITE    = Y.FROM_SITE
                              AND X.BOD_ID       = Y.BOD_ID
                              AND X.YYYYMMDD     = Y.YYYYMMDD)
               AND X.ATTRIBUTE1 = 'Y';
            END IF;

        END IF;   /* SHIP PLAN 종료 */

        IF P_MEASURE IN  ('CELL_PROD') THEN
            /* CELL_PROD 시작 */
            INSERT
              INTO GT_XADSM_CHANGED_DATA
                 ( YYYYMMDD
                 , QTY )
            SELECT A.TOKEN AS YYYYMMDD
                 , CAST(B.TOKEN AS NUMBER(20,10)) AS QTY
              FROM TABLE(UF_FX_STRING_SPLIT(P_YMD_STRINGS, ',')) A
                 , TABLE(UF_FX_STRING_SPLIT(P_QTY_STRINGS, ',')) B
             WHERE A.NR = B.NR
               AND B.TOKEN <> '-9';


            IF P_IS_DEBUG = 1 THEN
                FOR R IN (SELECT COUNT(*) CNT
                            FROM GT_XADSM_CHANGED_DATA) LOOP
                    DBMS_OUTPUT.PUT_LINE('@CHANGED_DATA ROWS=' || TO_CHAR(R.CNT));
                END LOOP;
            END IF;


            DELETE
              FROM GT_XADSM_SAPP;

            INSERT
              INTO GT_XADSM_SAPP
                 ( DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CELL_QTY )
            SELECT X.DIVISION_ID
                 , X.PLAN_START_YYYYMMDD
                 , X.PLAN_TYPE
                 , X.SEQ
                 , CAST('A' AS VARCHAR2(10 CHAR)) AS OPERATION_GROUP
                 , X.FROM_SITE AS SCM_SITE_ID
                 , X.ITEM_ID
                 , X.PROD_LINE AS LINE_ID
                 , X.ATTRIBUTE9 AS OPERATION_ID
                 , 'PROD_PLAN_AMEND' AS MEASURE
                 , Y.YYYYMMDD
                 , Y.QTY
                 , X.DIVISION_ID AS ORIGIN_DIVISION_ID
                 , '' AS ELECTRODE_TYPE
                 , '0' AS CELL_QTY
              FROM (SELECT *
                      FROM SCP_XLS_PSI_GLOBAL_SMALL
                     WHERE DIVISION_ID          = P_DIVISION_ID
                       AND CREATE_FROM_YYYYMMDD = P_CREATE_FROM_YYYYMMDD
                       AND XLS_KEY1             = V_XLS_KEY1) X

              FULL OUTER JOIN GT_XADSM_CHANGED_DATA Y
                ON 1 = 1;
            /* WHERE  Y.YYYYMMDD BETWEEN @v_bod_from AND @v_bod_to  FROZEN 구간 고려가능 */


            IF P_IS_DEBUG = 1 THEN
                FOR R IN (SELECT COUNT(*) CNT
                            FROM GT_XADSM_SAPP) LOOP
                    DBMS_OUTPUT.PUT_LINE('#SCP_ANL_PRODUCTION_PLAN ROWS=' || TO_CHAR(R.CNT));
                END LOOP;
            END IF;

            /* PROD_PLAN_AMEND */
            /* ------------------------------------------------------------------------------------------
             * 원본 L458~630 : INSERT INTO SCP_ANL_PRODUCTION_PLAN (..)
             *                 SELECT .. FROM ( MERGE .. OUTPUT $action, Inserted.* ) AS Changes(..)
             *                 WHERE Action = 'INSERT'   (T-SQL composable DML)
             *   ① MERGE 가 INSERT 한 행에 대해서만 ② MEASURE='PROD_PLAN_ENGINE', QTY=0 인 짝행을 추가 INSERT
             * 이므로 두 문장으로 분해한다. MERGE 의 ON 키에 MEASURE 가 포함되어 있고 짝행의 MEASURE 는
             * 'PROD_PLAN_ENGINE' 으로 원천행 MEASURE('PROD_PLAN_AMEND') 와 다르므로, 짝행을 먼저 넣어도
             * ------------------------------------------------------------------------------------------ */
            /* INSERT 일경우 PROD_PLAN_ENGINE/PROD_PLAN_AMEND 쌍으로 입력한다. */
            INSERT
              INTO SCP_ANL_PRODUCTION_PLAN
                 ( DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , OPERATION_GROUP
        /*                             ,CELL_ITEM_ID */
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CELL_QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            SELECT Y.DIVISION_ID
                 , Y.PLAN_START_YYYYMMDD
                 , Y.PLAN_TYPE
                 , Y.SEQ
                 , Y.OPERATION_GROUP
                 , Y.SCM_SITE_ID
                 , Y.ITEM_ID
                 , Y.LINE_ID
                 , Y.OPERATION_ID
                 , 'PROD_PLAN_ENGINE' AS MEASURE
                 , Y.YYYYMMDD
                 , 0 AS QTY
                 , Y.ORIGIN_DIVISION_ID
                 , Y.ELECTRODE_TYPE
                 , Y.CELL_QTY
                 , V_USER_ID_SIM AS CREATED_BY
                 , SYSDATE AS CREATION_DATE
                 , V_USER_ID_SIM AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
              FROM GT_XADSM_SAPP Y
             WHERE NOT EXISTS (SELECT 1
                                 FROM SCP_ANL_PRODUCTION_PLAN X
                                WHERE 0 = 0
                                  AND X.DIVISION_ID         = Y.DIVISION_ID
                                  AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD
                                  AND X.PLAN_TYPE           = Y.PLAN_TYPE
                                  AND X.SEQ                 = Y.SEQ
                                  AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                                  AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                                  AND X.ITEM_ID             = Y.ITEM_ID
                                  AND X.MEASURE             = Y.MEASURE
                                  AND X.YYYYMMDD            = Y.YYYYMMDD
                                  AND X.LINE_ID             = Y.LINE_ID
                                  AND X.OPERATION_ID        = Y.OPERATION_ID
                                  AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                                  AND NVL(X.ELECTRODE_TYPE, '#') = NVL(Y.ELECTRODE_TYPE, '#'));

            MERGE INTO SCP_ANL_PRODUCTION_PLAN X
            USING (SELECT DIVISION_ID
                        , PLAN_START_YYYYMMDD
                        , PLAN_TYPE
                        , SEQ
                        , OPERATION_GROUP
                        , SCM_SITE_ID
                        , ITEM_ID
                        , LINE_ID
                        , OPERATION_ID
                        , MEASURE
                        , YYYYMMDD
                        , QTY
                        , ORIGIN_DIVISION_ID
                        , ELECTRODE_TYPE
                        , CELL_QTY
                     FROM GT_XADSM_SAPP) Y
               ON (0 = 0
              AND X.DIVISION_ID         = Y.DIVISION_ID           /* @p_division_id				-- 2021.10.25 튜닝개선요청에 따른 변경 */
              AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD   /* @p_PLAN_START_YYYYMMDD */
              AND X.PLAN_TYPE           = Y.PLAN_TYPE             /* @p_PLAN_TYPE */
              AND X.SEQ                 = Y.SEQ                   /* @p_SEQ */
              AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
              AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
              AND X.ITEM_ID             = Y.ITEM_ID
              AND X.MEASURE             = Y.MEASURE
              AND X.YYYYMMDD            = Y.YYYYMMDD
              AND X.LINE_ID             = Y.LINE_ID
              AND X.OPERATION_ID        = Y.OPERATION_ID
              AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                  /*                   * NULL = NULL 이 UNKNOWN 이라 전건이 NOT MATCHED -> INSERT 로 뒤집혀 PK 위반(ORA-00001)이 난다. */
              AND NVL(X.ELECTRODE_TYPE, '#') = NVL(Y.ELECTRODE_TYPE, '#'))
            WHEN MATCHED THEN
            UPDATE
               SET X.QTY               = Y.QTY
                 , X.LAST_UPDATED_BY   = V_USER_ID_SIM
                 , X.LAST_UPDATE_DATE  = SYSDATE
            WHEN NOT MATCHED THEN
            INSERT ( DIVISION_ID
                   , PLAN_START_YYYYMMDD
                   , PLAN_TYPE
                   , SEQ
                   , OPERATION_GROUP
                   , SCM_SITE_ID
                   , ITEM_ID
                   , LINE_ID
                   , OPERATION_ID
                   , MEASURE
                   , YYYYMMDD
                   , QTY
                   , ORIGIN_DIVISION_ID
                   , ELECTRODE_TYPE
                   , CELL_QTY
                   , CREATED_BY
                   , CREATION_DATE
                   , LAST_UPDATED_BY
                   , LAST_UPDATE_DATE )
            VALUES ( Y.DIVISION_ID
                   , Y.PLAN_START_YYYYMMDD
                   , Y.PLAN_TYPE
                   , Y.SEQ
                   , Y.OPERATION_GROUP
                   , Y.SCM_SITE_ID
                   , Y.ITEM_ID
                   , Y.LINE_ID
                   , Y.OPERATION_ID
                   , Y.MEASURE
                   , Y.YYYYMMDD
                   , Y.QTY
                   , Y.ORIGIN_DIVISION_ID
                   , Y.ELECTRODE_TYPE
                   , Y.CELL_QTY
                   , V_USER_ID_SIM
                   , SYSDATE
                   , V_USER_ID_SIM
                   , SYSDATE );

            /* SCP_ANL_PRODUCTION_PLAN_H (등록) */
            IF P_IS_DEBUG = 0 THEN
            INSERT
              INTO SCP_ANL_PRODUCTION_PLAN_H
                 ( HISTORY_SEQ
                 , DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , HISTORY_CREATION_DATE )
            SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
                 , DIVISION_ID
                 , PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , SEQ
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , V_USER_ID_SIM AS CREATED_BY
                 , SYSDATE AS CREATION_DATE
                 , V_USER_ID_SIM AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , SYSDATE AS HISTORY_CREATION_DATE
              FROM GT_XADSM_SAPP;
            END IF;

            IF P_IS_DEBUG = 0 THEN
            UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
               SET X.QTY               = (SELECT Y.QTY
                                            FROM GT_XADSM_SAPP Y
                                           WHERE 0 = 0
                                             AND X.DIVISION_ID     = Y.DIVISION_ID
                                             AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                                             AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                                             AND X.ITEM_ID         = Y.ITEM_ID
                                             AND X.LINE_ID         = Y.LINE_ID
                                             AND X.OPERATION_ID    = Y.OPERATION_ID
                                             AND X.YYYYMMDD        = Y.YYYYMMDD
                                             AND ROWNUM = 1)
                 , X.ATTRIBUTE1        = 'Y'
                 , X.LAST_UPDATED_BY   = V_USER_ID_SIM
                 , X.LAST_UPDATE_DATE  = SYSDATE
             WHERE EXISTS (SELECT 1
                             FROM GT_XADSM_SAPP Y
                            WHERE 0 = 0
                              AND X.DIVISION_ID     = Y.DIVISION_ID
                              AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                              AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                              AND X.ITEM_ID         = Y.ITEM_ID
                              AND X.LINE_ID         = Y.LINE_ID
                              AND X.OPERATION_ID    = Y.OPERATION_ID
                              AND X.YYYYMMDD        = Y.YYYYMMDD);
            END IF;

            /* ------------------------------------------------------------------------------------- */
            /* SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력 */
            /* ------------------------------------------------------------------------------------- */
            IF P_IS_DEBUG = 0 THEN
            INSERT
              INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
                 ( HISTORY_SEQ
                 , FIX_ID
                 , DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , YYYYMMDD
                 , QTY
                 , FIX_REASON
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 /* ,ATTRIBUTE1 */
                 /* ,ATTRIBUTE2 */
                 /* ,ATTRIBUTE3 */
                 /* ,ATTRIBUTE4 */
                 /* ,ATTRIBUTE5 */
                 /* ,ATTRIBUTE6 */
                 /* ,ATTRIBUTE7 */
                 /* ,ATTRIBUTE8 */
                 /* ,ATTRIBUTE9 */
                 /* ,ATTRIBUTE10 */
                 , HISTORY_CREATION_DATE )
            SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
                 , FIX_ID
                 , DIVISION_ID
                 , OPERATION_GROUP
                 , SCM_SITE_ID
                 , ITEM_ID
                 , LINE_ID
                 , OPERATION_ID
                 , YYYYMMDD
                 , QTY
                 , FIX_REASON
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 , V_USER_ID_SIM AS CREATED_BY
                 , SYSDATE AS CREATION_DATE
                 , V_USER_ID_SIM AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , SYSDATE AS HISTORY_CREATION_DATE
              FROM SCP_ANL_PRODUCTION_PLAN_FIX
             WHERE ATTRIBUTE1 = 'Y';
            END IF;

            /* FIX  수정 */
            IF P_IS_DEBUG = 0 THEN
            UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
               SET X.ATTRIBUTE1 = NULL   /* History 구분을 위해 원상복구 */
             WHERE EXISTS (SELECT 1
                             FROM GT_XADSM_SAPP Y
                            WHERE 0 = 0
                              AND X.DIVISION_ID     = Y.DIVISION_ID
                              AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                              AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                              AND X.ITEM_ID         = Y.ITEM_ID
                              AND X.LINE_ID         = Y.LINE_ID
                              AND X.OPERATION_ID    = Y.OPERATION_ID
                              AND X.YYYYMMDD        = Y.YYYYMMDD)
               AND X.ATTRIBUTE1 = 'Y';
            END IF;

        END IF;   /* CELL PROD 종료 */

        /* ----------------------------------------------------- */
        /* 실행 Logic END */
        /* ----------------------------------------------------- */
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        D_EVENT_DATE  := SYSDATE;
        /* 원본은 @@ROWCOUNT 를 넘긴다. 바로 앞 문장이 FROM 없는 대입형 SELECT 이므로 T-SQL 규칙상 */
        IF P_IS_DEBUG = 0 THEN
            PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, 'TXN', 1, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_USER_ID);
        END IF;

    EXCEPTION
        WHEN OTHERS THEN

            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);

            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            IF P_IS_DEBUG = 0 THEN
                PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', 1, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_USER_ID);
            END IF;
    END;

    /* 임시 운영반영시에 주석처리 할것. */

    V_EXEC_TIME := LPAD(TO_CHAR(TRUNC(ROUND((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0') || ':' ||
                   LPAD(TO_CHAR(MOD(ROUND((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0');
    /* 종료 LOG */
    V_LOG_MESSAGE := '########## END of procedure ##########';
    D_EVENT_DATE  := SYSDATE;

    V_DESCRIPTION := CASE WHEN P_DIVISION_ID IS NULL
                            OR P_PLAN_START_YYYYMMDD IS NULL
                            OR P_MEASURE IS NULL
                            OR V_XLS_KEY1 IS NULL
                            OR V_EXEC_TIME IS NULL
                          THEN NULL
                          ELSE '[' || P_DIVISION_ID || '][' || P_PLAN_START_YYYYMMDD || '][' || P_MEASURE || '][' || LPAD(TO_CHAR(V_XLS_KEY1), 10) || '][' || V_EXEC_TIME || ']'
                     END;
    IF P_IS_DEBUG = 0 THEN
        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 1, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_USER_ID);
    END IF;


    RETURN;
END;   /* BODY */